public class Geheimsprache {
    static int vokale(String wort) {
        int anzahl = 0;
        String klein = wort.toLowerCase();
        for (int i = 0; i < klein.length(); i++) {
            if ("aeiou".indexOf(klein.charAt(i)) >= 0) {
                anzahl++;
            }
        }
        return anzahl;
    }
}

