public class Schatzkammer {
    private int gold;

    public Schatzkammer(int gold) {
        this.gold = gold;
    }

    public int abheben(int menge) {
        if (menge < 1 || menge > gold) {
            throw new IllegalArgumentException("Ungültige Menge: " + menge);
        }
        gold = gold - menge;
        return gold;
    }
}

